// Carousel component for Perfect For section
function PerfectForCarousel() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  const creatorTypes = [
    { name: "Content Creators", icon: IconVideo },
    { name: "Streamers & Gamers", icon: IconDeviceGamepad2 },
    { name: "Social Media Influencers", icon: IconBrandInstagram },
    { name: "Podcasters", icon: IconMicrophone },
    { name: "Digital Artists", icon: IconPalette },
    { name: "Creator Business", icon: IconTrendingUp },
  ];

  const checkScrollPosition = () => {
    if (scrollRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } = scrollRef.current;
      setCanScrollLeft(scrollLeft > 0);
      setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 1);
    }
  };

  useEffect(() => {
    const scrollContainer = scrollRef.current;
    if (scrollContainer) {
      scrollContainer.addEventListener("scroll", checkScrollPosition);
      checkScrollPosition();
      return () =>
        scrollContainer.removeEventListener("scroll", checkScrollPosition);
    }
  }, []);

  const scroll = (direction: "left" | "right") => {
    if (scrollRef.current) {
      const scrollAmount = 300;
      const currentScroll = scrollRef.current.scrollLeft;
      const targetScroll =
        direction === "left"
          ? currentScroll - scrollAmount
          : currentScroll + scrollAmount;

      scrollRef.current.scrollTo({
        left: targetScroll,
        behavior: "smooth",
      });
    }
  };

  return (
    <div className="relative">
      <div className="flex items-center justify-between mb-6">
        <div className="text-center flex-1">
          <h2 className="text-3xl md:text-4xl font-bold mb-4">Perfect For</h2>
          <p className="text-xl md:text-2xl text-muted-foreground">
            Built for creators of all types and sizes
          </p>
        </div>
        <div className="flex gap-2 ml-4">
          <Button
            variant="outline"
            size="sm"
            onClick={() => scroll("left")}
            disabled={!canScrollLeft}
            className="h-10 w-10 p-0"
          >
            <IconChevronLeft className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => scroll("right")}
            disabled={!canScrollRight}
            className="h-10 w-10 p-0"
          >
            <IconChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <div className="relative">
        <div
          ref={scrollRef}
          className="flex gap-4 overflow-x-auto scrollbar-hide pb-4"
          style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
        >
          {creatorTypes.map((item, index) => (
            <Card
              key={index}
              className="text-center flex-shrink-0 w-48 min-h-[120px] 
                hover:shadow-md transition-shadow duration-200"
            >
              <CardContent
                className="py-4 flex flex-col items-center justify-center 
                  h-full gap-2"
              >
                <item.icon className="h-6 w-6 text-primary" />
                <p className="font-semibold text-sm md:text-base leading-tight">
                  {item.name}
                </p>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </div>
  );
}

